    's.mailroom.1': "Куриерът носи колет.", // nieuw, nalezen // nagelezen AI 28 nov
    's.mailroom.2': "Сложи писмата в правилната пощенска кутийка.", // nieuw, nalezen // nagelezen AI 28 nov
