    's.rawcooked.1': "Суровото месо се слага най-долу в хладилника.", // nieuw, nalezen // nagelezen AI 28 nov
    's.rawcooked.2': "Готово ли е вече пилето?", // nieuw, nalezen // nagelezen AI 28 nov
